'use client';

// PROTOTYPE tooling: cycles ?variant= on a page. Renders nothing in production builds.

import { useEffect } from 'react';
import { ArrowLeft, ChevronRight } from './Icons';

type Variant = { key: string; name: string };

export function PrototypeSwitcher({
  variants,
  current,
  onChange,
  extra,
}: {
  variants: readonly Variant[];
  current: string;
  onChange: (key: string) => void;
  extra?: React.ReactNode;
}) {
  const i = Math.max(0, variants.findIndex((v) => v.key === current));
  const step = (d: number) => onChange(variants[(i + d + variants.length) % variants.length]!.key);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const el = document.activeElement;
      if (el instanceof HTMLInputElement || el instanceof HTMLTextAreaElement || (el as HTMLElement)?.isContentEditable) return;
      if (e.key === 'ArrowLeft') step(-1);
      if (e.key === 'ArrowRight') step(1);
    };
    addEventListener('keydown', onKey);
    return () => removeEventListener('keydown', onKey);
  });

  if (process.env.NODE_ENV === 'production') return null;
  const v = variants[i]!;
  return (
    <div className="proto-switcher" role="toolbar" aria-label="Prototype variants">
      <button onClick={() => step(-1)} aria-label="Previous variant">
        <ArrowLeft />
      </button>
      <span>
        {v.key} ({v.name})
      </span>
      <button onClick={() => step(1)} aria-label="Next variant">
        <ChevronRight />
      </button>
      {extra}
    </div>
  );
}
