'use client';

import '@fontsource/lilex/400.css';
import '@fontsource/lilex/500.css';
import '@fontsource/lilex/700.css';
import { useCallback, useEffect, useRef, useState, type FormEvent } from 'react';
import { api, Unauthorized } from '@/lib/api';
import { Lockup } from '@/components/Logo';
import { PrototypeSwitcher } from '@/components/PrototypeSwitcher';
import { RepoBadge } from '@/components/RepoBadge';
import { Sea, type SeaState } from '@/components/Sea';
import { VARIANTS, useVariant, type LoginError } from './toast-prototype';

export default function Login() {
  const [token, setToken] = useState('');
  const [state, setState] = useState<SeaState>('idle');
  const [error, setError] = useState<LoginError | null>(null);
  const [attempts, setAttempts] = useState(0);
  const [host, setHost] = useState('');
  const [variant, setVariant] = useVariant();
  const form = useRef<HTMLFormElement>(null);
  const input = useRef<HTMLInputElement>(null);
  useEffect(() => setHost(window.location.host), []);
  const busy = state === 'busy' || state === 'ok';

  const fail = (kind: LoginError['kind']) => {
    setError({ id: Date.now(), kind, at: new Date() });
    setAttempts((n) => n + 1);
    setState('error');
  };

  const submit = async (e: FormEvent) => {
    e.preventDefault();
    setState('busy');
    try {
      await api.login(token.trim());
      setError(null);
      setState('ok');
      // Lets the tide cover the screen before the app replaces it.
      const wait = matchMedia('(prefers-reduced-motion: reduce)').matches ? 0 : 650;
      setTimeout(() => window.location.assign('/'), wait);
    } catch (err) {
      fail(err instanceof Unauthorized ? 'token' : 'down');
    }
  };

  const dismiss = useCallback(() => setError(null), []);
  const retry = () => {
    setError(null);
    input.current?.select();
    input.current?.focus();
  };

  useEffect(() => {
    if (!error) return;
    const onKey = (e: KeyboardEvent) => e.key === 'Escape' && dismiss();
    addEventListener('keydown', onKey);
    return () => removeEventListener('keydown', onKey);
  }, [error, dismiss]);

  const Toast = variant.Toast;
  return (
    <main className="login" data-state={state}>
      <Sea state={state} above={form} />
      <div className="login-side">
        <Lockup height={34} />
        <div>
          <h1>Your agents are waiting on the shore.</h1>
          <p className="login-lead">Paste the access token</p>
        </div>
        <form ref={form} onSubmit={submit}>
          <label className="visually-hidden" htmlFor="token">
            Access token
          </label>
          <div className="login-row">
            <input
              ref={input}
              id="token"
              type="password"
              autoComplete="current-password"
              autoFocus
              required
              readOnly={busy}
              aria-invalid={state === 'error'}
              value={token}
              onChange={(e) => {
                setToken(e.target.value);
                if (state === 'error') setState('idle');
              }}
              placeholder="orla_…"
              spellCheck={false}
            />
            <button disabled={busy || !token.trim()}>{busy ? 'Logging in…' : 'Log in'}</button>
          </div>
        </form>
      </div>

      <Toast error={error} attempts={attempts} onDismiss={dismiss} onRetry={retry} />

      <footer className="login-foot">
        <RepoBadge />
        <span className="login-addr" aria-hidden="true">
          {host}
        </span>
      </footer>

      <PrototypeSwitcher
        variants={VARIANTS}
        current={variant.key}
        onChange={(k) => {
          setError(null);
          setVariant(k);
        }}
        extra={
          <>
            <button className="proto-fire" onClick={() => fail('token')}>
              Wrong token
            </button>
            <button className="proto-fire" onClick={() => fail('down')}>
              Server down
            </button>
          </>
        }
      />
    </main>
  );
}
