'use client';

// PROTOTYPE, throwaway: three ways to show a login error, switched with ?variant= on /login.
// Once one wins, fold it into the real page and keep this file only on a prototype branch.

import { useEffect, useRef, useState } from 'react';
import { Ban, Cross } from '@/components/Icons';

export type LoginError = { id: number; kind: 'token' | 'down'; at: Date };

export const COPY = {
  token: { title: 'Wrong token', body: 'That is not this server’s token. Copy it again from the token file.' },
  down: { title: 'Orla did not answer', body: 'Check that it is running and try again.' },
};

type Props = { error: LoginError | null; attempts: number; onDismiss: () => void; onRetry: () => void };

const reduce = () => typeof window !== 'undefined' && matchMedia('(prefers-reduced-motion: reduce)').matches;

/* A. Buoy: a slim pill that drops from the top and drains away after 6 seconds. */
function ToastA({ error, onDismiss }: Props) {
  const [paused, setPaused] = useState(false);
  useEffect(() => {
    if (!error || paused) return;
    const t = setTimeout(onDismiss, 6000);
    return () => clearTimeout(t);
  }, [error, paused, onDismiss]);
  if (!error) return null;
  return (
    <div
      key={error.id}
      className="tA"
      role="alert"
      onMouseEnter={() => setPaused(true)}
      onMouseLeave={() => setPaused(false)}
      onFocus={() => setPaused(true)}
      onBlur={() => setPaused(false)}
    >
      <span className="tA-icon">
        <Ban />
      </span>
      <p>
        <b>{COPY[error.kind].title}.</b> {COPY[error.kind].body}
      </p>
      <button className="tA-close" onClick={onDismiss} aria-label="Dismiss">
        <Cross />
      </button>
      <span className="tA-drain" data-paused={paused} aria-hidden="true" />
    </div>
  );
}

/* B. Rises from the sea: a card under the form that stays until dismissed, with the recovery as its action. */
function ToastB({ error, attempts, onDismiss, onRetry }: Props) {
  if (!error) return null;
  return (
    <div key={error.id} className="tB" role="alert">
      <div className="tB-head">
        <h2>{COPY[error.kind].title}</h2>
        {attempts > 1 && <span className="tB-count">Attempt {attempts}</span>}
      </div>
      <p>{COPY[error.kind].body}</p>
      <div className="tB-actions">
        <button className="tB-primary" onClick={onRetry}>
          {error.kind === 'token' ? 'Paste again' : 'Try again'}
        </button>
        <button className="tB-ghost" onClick={onDismiss}>
          Dismiss
        </button>
      </div>
    </div>
  );
}

/* C. Shore log: every failed attempt is a line at the foot of the screen, newest bright, like the server log. */
function ToastC({ error, onDismiss }: Props) {
  const [lines, setLines] = useState<LoginError[]>([]);
  const seen = useRef(0);
  useEffect(() => {
    if (error && error.id !== seen.current) {
      seen.current = error.id;
      setLines((l) => [...l, error].slice(-3));
    }
    if (!error) setLines([]);
  }, [error]);
  if (!lines.length) return null;
  const time = (d: Date) => d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false });
  return (
    <div className="tC" role="log" aria-live="assertive">
      <ol>
        {lines.map((l, i) => (
          <li key={l.id} data-latest={i === lines.length - 1}>
            <time>{time(l.at)}</time>
            <span className="tC-level">error</span>
            <span>{COPY[l.kind].body}</span>
          </li>
        ))}
      </ol>
      <button className="tC-clear" onClick={onDismiss}>
        Clear
      </button>
    </div>
  );
}

export const VARIANTS = [
  { key: 'A', name: 'Buoy pill', Toast: ToastA },
  { key: 'B', name: 'Rises from the sea', Toast: ToastB },
  { key: 'C', name: 'Shore log', Toast: ToastC },
] as const;

export function useVariant() {
  const [v, setV] = useState<string>('A');
  useEffect(() => {
    const read = () => setV(new URLSearchParams(window.location.search).get('variant') ?? 'A');
    read();
    addEventListener('popstate', read);
    return () => removeEventListener('popstate', read);
  }, []);
  const set = (next: string) => {
    const url = new URL(window.location.href);
    url.searchParams.set('variant', next);
    window.history.replaceState(null, '', url);
    setV(next);
  };
  return [VARIANTS.find((x) => x.key === v) ?? VARIANTS[0], set] as const;
}

export { reduce as prefersReducedMotion };
